"""Natural-language prompt families and machine-parseable answer targets."""

from __future__ import annotations

import json
from typing import Literal

from robot_observability.constants import JOINT_NAMES

Intent = Literal[
    "summary",
    "contact",
    "semantics",
    "onset",
    "strongest_joint",
    "affected_joints",
    "evidence_interval",
]

INTENTS: tuple[Intent, ...] = (
    "summary",
    "contact",
    "semantics",
    "onset",
    "strongest_joint",
    "affected_joints",
    "evidence_interval",
)

PROMPTS: dict[Intent, tuple[str, ...]] = {
    "summary": (
        "Diagnose this robot telemetry window.",
        "Summarize the contact event and identify the supporting temporal evidence.",
    ),
    "contact": (
        "Did external contact occur?",
        "Does this window contain evidence of physical contact?",
    ),
    "semantics": (
        "Was the motion free, an intentional contact, or an accidental collision?",
        "Classify the interaction semantics.",
    ),
    "onset": (
        "When did external contact begin?",
        "Give the contact onset relative to the start of this window in milliseconds.",
    ),
    "strongest_joint": (
        "Which joint has the strongest normalized disturbance evidence?",
        "Identify the joint whose torque signal most strongly supports the diagnosis.",
    ),
    "affected_joints": (
        "Which joints are materially affected, ranked by disturbance?",
        "List the joints crossing the calibrated disturbance threshold.",
    ),
    "evidence_interval": (
        "Where is the strongest temporal evidence?",
        "Return the interval containing sustained disturbance evidence.",
    ),
}


def answer_payload(metadata: dict[str, object], intent: Intent) -> dict[str, object]:
    complete = {
        "contact": bool(metadata["contact"]),
        "event_type": metadata["event_type"],
        "onset_ms": metadata["onset_sample"],
        "strongest_joint": metadata["strongest_joint"],
        "affected_joints": metadata["affected_joints"],
        "evidence_start_ms": metadata["evidence_start_ms"],
        "evidence_end_ms": metadata["evidence_end_ms"],
    }
    keys: dict[Intent, tuple[str, ...]] = {
        "summary": tuple(complete),
        "contact": ("contact",),
        "semantics": ("event_type",),
        "onset": ("onset_ms",),
        "strongest_joint": ("strongest_joint",),
        "affected_joints": ("affected_joints",),
        "evidence_interval": ("evidence_start_ms", "evidence_end_ms"),
    }
    return {key: complete[key] for key in keys[intent]}


def evidence_sentence(metadata: dict[str, object]) -> str:
    if not metadata["contact"]:
        return (
            "Across J1–J7, no sustained torque disturbance crosses the threshold calibrated only "
            "on training free-motion recordings, so no localized onset or responsible joint is supported."
        )
    scores = list(metadata["joint_scores"])
    ranked = sorted(zip(JOINT_NAMES, scores), key=lambda pair: -pair[1])
    affected = list(metadata["affected_joints"])
    affected_text = ", ".join(affected) if affected else "no additional joints"
    return (
        f"A sustained torque excursion begins near {metadata['onset_sample']} ms and its strongest "
        f"evidence spans {metadata['evidence_start_ms']}–{metadata['evidence_end_ms']} ms; "
        f"{ranked[0][0]} has the largest normalized disturbance, with threshold-crossing support "
        f"from {affected_text}."
    )


def target_text(
    metadata: dict[str, object],
    intent: Intent,
    output_format: str = "answer_then_evidence",
) -> str:
    payload = json.dumps(answer_payload(metadata, intent), separators=(",", ":"), sort_keys=True)
    rationale = evidence_sentence(metadata)
    if output_format == "answer_then_evidence":
        return f"Answer: {payload}\nEvidence: {rationale}"
    if output_format == "rationale_then_answer":
        return f"Rationale: {rationale}\nAnswer: {payload}"
    raise ValueError(f"Unknown output format: {output_format}")


def channel_descriptions(metadata: dict[str, object]) -> list[str]:
    del metadata
    return [
        (
            f"{joint} external joint torque in Nm, sampled at 1000 Hz over 1.024 seconds. "
            "The numeric values are normalized with train-only robust statistics."
        )
        for joint in JOINT_NAMES
    ]
"""Adapter from prepared robot windows to OpenTSLM's sample contract."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from robot_observability.prepared import PreparedSplit
from robot_observability.qa import INTENTS, PROMPTS, answer_payload, channel_descriptions, target_text


class RobotQADataset:
    """A torch-compatible dataset without importing torch at module import time."""

    def __init__(
        self,
        root: Path,
        split: str,
        *,
        mode: str = "summary_plus_atomic",
        seed: int = 20260912,
        eos_token: str = "",
        output_format: str = "answer_then_evidence",
    ) -> None:
        self.prepared = PreparedSplit(root, split)
        if mode not in {"mixed", "summary", "summary_plus_atomic", "all_intents"}:
            raise ValueError(f"Unknown prompt mode: {mode}")
        self.mode = mode
        self.seed = seed
        self.eos_token = eos_token
        if output_format not in {"answer_then_evidence", "rationale_then_answer"}:
            raise ValueError(f"Unknown output format: {output_format}")
        self.output_format = output_format

    def __len__(self) -> int:
        multiplier = (
            len(INTENTS) if self.mode == "all_intents" else 2 if self.mode == "summary_plus_atomic" else 1
        )
        return len(self.prepared) * multiplier

    def __getitem__(self, index: int) -> dict[str, object]:
        import torch

        multiplier = (
            len(INTENTS) if self.mode == "all_intents" else 2 if self.mode == "summary_plus_atomic" else 1
        )
        row_index, intent_index = divmod(index, multiplier)
        signal, metadata = self.prepared[row_index]
        if self.mode == "all_intents":
            intent = INTENTS[intent_index]
        elif self.mode == "mixed":
            digest = hashlib.sha256(f"{self.seed}:{metadata['record_id']}:mixed".encode()).digest()
            if digest[0] % 2 == 0:
                intent = "summary"
            else:
                intent = INTENTS[1 + int.from_bytes(digest[1:5], "big") % (len(INTENTS) - 1)]
        elif self.mode == "summary_plus_atomic" and intent_index == 1:
            digest = hashlib.sha256(f"{self.seed}:{metadata['record_id']}:atomic".encode()).digest()
            intent = INTENTS[1 + int.from_bytes(digest[:4], "big") % (len(INTENTS) - 1)]
        else:
            intent = "summary"
        variants = PROMPTS[intent]
        digest = hashlib.sha256(f"{self.seed}:{metadata['record_id']}:{intent}".encode()).digest()
        question = variants[int.from_bytes(digest[:4], "big") % len(variants)]
        schema_keys = list(answer_payload(metadata, intent))
        schema = json.dumps(schema_keys, separators=(",", ":"))
        if self.output_format == "rationale_then_answer":
            response_contract = (
                "First write `Rationale:` as one natural paragraph grounded in temporal and joint "
                "patterns. Do not use headings inside it or name the interaction class before the "
                f"final line. End with `Answer:` and one closed compact JSON object containing only {schema}. "
            )
        else:
            response_contract = (
                f"Respond with `Answer:` and one closed compact JSON object containing only {schema}. "
            )
        return {
            "pre_prompt": (
                "You are analyzing synchronized KUKA LWR4+ external-joint-torque telemetry. "
                "Use the numeric time series as primary evidence. "
            ),
            "time_series_text": channel_descriptions(metadata),
            "time_series": torch.from_numpy(signal.astype("float32", copy=True)),
            "post_prompt": (
                f"\nQuestion: {question}\n"
                f"{response_contract}"
                "Use JSON types exactly: booleans are true/false, numbers are unquoted, arrays are "
                "arrays, and missing values are null. Never quote a boolean, number, or null. "
                + (
                    ""
                    if self.output_format == "rationale_then_answer"
                    else "Then write one short `Evidence:` sentence."
                )
            ),
            "answer": target_text(metadata, intent, self.output_format) + self.eos_token,
            "record_id": metadata["record_id"],
            "intent": intent,
            "metadata": metadata,
        }

