import { useMemo } from 'react';
import { ArrowUpRight, ChevronRight, Flag, Info } from 'lucide-react';
import { selectWindow } from '../lib/data';
import { COLORS, intervalLabel } from '../lib/format';
import type { DemoData, Interval, Marker } from '../types';
import { markerWindow } from './markerAnalysis';

type Props = { data: DemoData; playhead: number; interval: Interval; highlighted: string[]; onMarker: (marker: Marker) => void; onHighlight: (id: string) => void; onData: () => void };
export default function RecordingExplorer({ data, playhead, interval, highlighted, onMarker, onHighlight, onData }: Props) {
  const next = data.events.find(e => e.timeSeconds > playhead);
  const selectedMarker = data.events.find(event => event.timeSeconds >= interval.start && event.timeSeconds < interval.end);
  const selectedMarkerWindow = selectedMarker ? markerWindow(selectedMarker, data.recording.durationSeconds) : null;
  const selectedMarkerHasRaw = selectedMarkerWindow ? selectedMarkerWindow.start >= data.detail.startSeconds && selectedMarkerWindow.end <= data.detail.endSeconds : false;
  const stats = useMemo(() => {
    try { const w = selectWindow(data, interval); return { resolution: w.resolution, ranges: w.channels.map(c => ({ id: c.id, name: c.name, range: Math.max(...c.values)-Math.min(...c.values) })) }; } catch { return null; }
  }, [data, interval]);
  const maximum = Math.max(.001, ...(stats?.ranges.map(r => r.range) ?? [1]));
  const leading = stats?.ranges.reduce((a, b) => b.range > a.range ? b : a);
  return <section className="explorer-panel" aria-label="Recording explorer">
    <header className="panel-heading"><div><h2>Recording explorer</h2><span>{data.recording.id}</span></div><button className="text-button" onClick={onData}>Source details <ArrowUpRight size={14}/></button></header>
    <div className="recording-title"><h1>{data.recording.sourceUrl.includes("21927431") ? "KUKA LWR4+" : data.recording.name}</h1><p>Recorded torque experiment <span>{data.channels.length} joints · {data.recording.durationSeconds.toFixed(0)} s · {data.recording.sampleRateHz} Hz source</span></p></div>
    <div className="explorer-body">
      <aside className="event-browser"><div className="section-label"><Flag size={12}/>All markers <span>{data.events.length}</span></div><div className="event-list" aria-label="All publisher markers">{data.events.map(e => <button key={e.id} onClick={() => onMarker(e)} className={`event-item ${e.timeSeconds >= interval.start && e.timeSeconds < interval.end ? 'selected' : ''}`}><span className="event-tick"/><span>{e.label}<small>{e.timeSeconds.toFixed(3)} s</small></span><ChevronRight size={13}/></button>)}{!data.events.length && <p className="quiet-empty">No publisher markers in this recording.</p>}</div>{next && <button className="text-button next-marker" onClick={() => onMarker(next)}>Next marker <ChevronRight size={13}/></button>}</aside>
      <div className="range-overview"><div className="range-title"><h3>Torque range</h3><span className="mono">{intervalLabel(interval)}</span></div><div className="range-bars" aria-label="Maximum minus minimum torque per joint">{data.channels.map((channel, i) => { const value = stats?.ranges[i]?.range; return <button key={channel.id} className={`range-row ${highlighted.includes(channel.id) ? 'active' : ''}`} onClick={() => onHighlight(channel.id)} aria-label={`Highlight ${channel.name}, range ${value?.toFixed(3) ?? 'unavailable'} Nm`}><span>J{i+1}</span><div className="bar-track"><div style={{ width: `${(value ?? 0)/maximum*100}%`, background: COLORS[i] }}/></div><span className="mono">{value?.toFixed(3) ?? '—'} <small>Nm</small></span></button>; })}</div><div className="range-caption">{leading ? <><span>{leading.name}</span> has the widest excursion in this interval.</> : 'Select a replayed interval to compare joints.'}</div></div>
    </div>
    <footer className="explorer-footer"><details className="marker-explainer"><summary><Info size={13}/><span>{selectedMarker ? `${selectedMarker.label} · marker details` : 'What is a marker?'}</span></summary><div className="marker-detail"><strong>{selectedMarker ? `${selectedMarker.label} at ${selectedMarker.timeSeconds.toFixed(3)} s` : 'Publisher event marker'}</strong><p>This timestamp comes from <span className="mono">{selectedMarker?.source ?? 'JK_moments'}</span>, the dataset publisher's manual event annotation. It helps navigate the recording, but it is not an independently verified exact collision onset.</p>{selectedMarker && <p className="marker-analysis-status">{selectedMarkerHasRaw ? 'Selecting it automatically runs measured analysis and OpenTSLM on the surrounding raw window.' : 'Selecting it automatically summarizes the available display samples. OpenTSLM requires the full-resolution window from the data adapter.'}</p>}{selectedMarker && <button className="text-button" onClick={() => onMarker(selectedMarker)}>Analyze its context <ChevronRight size={13}/></button>}</div></details><span className="data-resolution">{stats?.resolution === 'raw' ? 'Raw samples' : 'Display samples'}</span></footer>
  </section>;
}
import { Component, lazy, Suspense, useState, type ReactNode } from 'react';
import { Box, ChartNoAxesCombined } from 'lucide-react';
import RecordingExplorer from './RecordingExplorer';
import type { DemoData, Interval, Marker } from '../types';
import type { PredictionCue } from '../assistant/predictionBrief';
const RobotPanel = lazy(() => import('../robot/RobotPanel'));

class RobotBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  render() { return this.state.failed ? <p className="robot-boundary" role="alert">3D could not open. Switch to Overview to continue inspecting the recording.</p> : this.props.children; }
}
type Props = { display?: 'overview' | 'robot'; prediction?: PredictionCue; datasetId: string; data: DemoData; playhead: number; interval: Interval; highlighted: string[]; onMarker: (marker: Marker) => void; onHighlight: (id: string) => void; onData: () => void };
export default function RecordingContext(props: Props) {
  const [localView, setView] = useState<'overview' | 'robot'>('overview');
  const view = props.display ?? localView;
  const isKuka = props.datasetId === 'zenodo-21927431';
  return <section className="recording-context" aria-label="Recording context">
    {!props.display && <div className="context-switch" role="group" aria-label="Recording context view">
      <button aria-pressed={view === 'overview'} onClick={() => setView('overview')}><ChartNoAxesCombined size={13}/>Overview</button>
      <button aria-pressed={view === 'robot'} disabled={!isKuka} title={isKuka ? 'Inspect measured articulation when available; body and base frame are schematic' : 'A robot mapping is not available for this recording'} onClick={() => setView('robot')}><Box size={13}/>3D reference</button>
    </div>}
    {view === 'overview' ? <RecordingExplorer {...props}/> : <RobotBoundary><Suspense fallback={<p className="robot-boundary" role="status">Opening 3D reference…</p>}><RobotPanel data={props.data} prediction={props.prediction} playhead={props.playhead} interval={props.interval} highlighted={props.highlighted} onHighlight={props.onHighlight}/></Suspense></RobotBoundary>}
  </section>;
}
import { useEffect, useRef, useState } from 'react';
import { ArrowLeft, ArrowRight, RotateCcw, ZoomIn, ZoomOut } from 'lucide-react';
import type { PredictionCue } from '../assistant/predictionBrief';
import { COLORS } from '../lib/format';
import type { DemoData, Interval } from '../types';
import { createRobotScene, validateGeometry, type RobotGeometry } from './scene';
import { positionAtPlayhead, positionFixture, torqueAtPlayhead, validatePositions, type PositionData } from './telemetry';

type Props = { prediction?: PredictionCue; data: DemoData; playhead: number; interval: Interval; highlighted: string[]; onHighlight: (id: string) => void };
export default function RobotPanel({ prediction, data, playhead, interval, highlighted, onHighlight }: Props) {
  const host = useRef<HTMLDivElement>(null);
  const scene = useRef<ReturnType<typeof createRobotScene> | null>(null);
  const callback = useRef(onHighlight); callback.current = onHighlight;
  const highlights = useRef(highlighted); highlights.current = highlighted;
  const cursor = useRef(playhead); cursor.current = playhead;
  const geometry = useRef<RobotGeometry | null>(null);
  const [positions, setPositions] = useState<PositionData | null>(null);
  const [positionError, setPositionError] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    const controller = new AbortController(); let alive = true;
    setLoading(true); setError(''); setPositions(null); setPositionError('');
    const positionUrl = positionFixture(data.recording.id);
    const positionRequest = positionUrl
      ? fetch(positionUrl, { signal: controller.signal }).then(async response => {
        if (!response.ok) throw new Error('Measured joint positions could not be loaded.');
        const value: unknown = await response.json(); validatePositions(value, data.recording.id);
        if ((value.endSeconds ?? value.times[value.times.length - 1]) > data.recording.durationSeconds + 1e-8) throw new Error('Position timing does not match this recording.');
        return { value, message: '' };
      }).catch(() => ({ value: null, message: 'Positions unavailable · fixed illustrative pose' }))
      : Promise.resolve({ value: null, message: 'No validated positions for this recording · fixed illustrative pose' });
    const geometryRequest = fetch('/robot/kuka/kinematics.json', { signal: controller.signal }).then(async response => {
      if (!response.ok) throw new Error('Robot reference could not be loaded.');
      const model: unknown = await response.json(); validateGeometry(model); return model;
    });
    Promise.all([geometryRequest, positionRequest]).then(([model, measured]) => {
      if (!alive || !host.current) return;
      geometry.current = model;
      if (measured.value && measured.value.joints.some((joint, index) => joint.values.some(angle => angle < model.joints[index].limitsRadians[0] - 1e-5 || angle > model.joints[index].limitsRadians[1] + 1e-5))) {
        measured = { value: null, message: 'Position mapping failed validation · fixed illustrative pose' };
      }
      const initial = measured.value ? positionAtPlayhead(measured.value, data.recording.id, cursor.current) : null;
      scene.current = createRobotScene(host.current, model, id => callback.current(id), () => {
        setError('The 3D graphics context was lost. Retry to restore it.');
      }, initial?.radians ?? model.illustrativePoseRadians);
      scene.current.highlight(highlights.current);
      setPositions(measured.value); setPositionError(measured.message);
    }).catch(reason => {
      if (alive && !controller.signal.aborted) setError(reason instanceof Error && reason.message.startsWith('Robot') ? reason.message : '3D is unavailable in this browser. The measured signals remain available.');
    }).finally(() => { if (alive) setLoading(false); });
    return () => { alive = false; controller.abort(); scene.current?.dispose(); scene.current = null; geometry.current = null; };
  }, [attempt, data.recording.id, data.recording.durationSeconds]);
  const atOnset = Boolean(prediction && Math.abs(playhead - prediction.onsetSeconds) <= .125);
  useEffect(() => { scene.current?.highlight(highlighted, atOnset ? prediction?.channelId : undefined); }, [highlighted, atOnset, prediction?.channelId, loading]);
  useEffect(() => {
    const measured = positions ? positionAtPlayhead(positions, data.recording.id, playhead) : null;
    const angles = measured?.radians ?? geometry.current?.illustrativePoseRadians;
    if (angles) scene.current?.pose(angles);
  }, [positions, playhead, data.recording.id]);
  const sample = torqueAtPlayhead(data, playhead);
  const measured = positions ? positionAtPlayhead(positions, data.recording.id, playhead) : null;
  const poseStatus = measured ? `Recorded articulation · ${measured.time.toFixed(3)} s` : loading ? 'Loading joint positions…' : 'Fixed illustrative pose';
  const selectedMarker = data.events.find(event => event.timeSeconds >= interval.start && event.timeSeconds < interval.end);
  return <div className="robot-panel">
    <div className="robot-caption"><strong>KUKA LWR4+ <span>· schematic</span></strong><span>{poseStatus}</span></div>
    <div className={`robot-event-cue${atOnset ? ' at-onset' : ''}`} aria-label="Robot event context">
      {prediction ? <><strong>{atOnset ? 'At predicted onset' : playhead < prediction.onsetSeconds ? 'Before predicted onset' : 'After predicted onset'} · {prediction.onsetSeconds.toFixed(3)} s</strong><span>{prediction.title}{prediction.channelId ? ` · strongest response J${prediction.channelId.slice(-1)}` : ''}. Highlight is a time cue, not an impact location.</span></> : selectedMarker ? <><strong>Publisher marker · {selectedMarker.timeSeconds.toFixed(3)} s</strong><span>Annotated event time. Analyze the interval for a model prediction.</span></> : <><strong>Recorded movement</strong><span>Select an event and analyze its torque to investigate contact.</span></>}
    </div>
    <div className="robot-content">
      <div className="robot-stage">
        <div className="robot-canvas" ref={host} role="img" aria-label={measured ? `Seven-joint schematic with recorded articulation at ${measured.time.toFixed(3)} seconds. Body shape and global base orientation are illustrative. Use joint buttons to highlight telemetry.` : 'Seven-joint robot schematic in a fixed illustrative pose. Measured articulation is unavailable at this time. Use joint buttons to highlight telemetry.'}/>
        {loading && <div className="robot-message" role="status">Loading robot reference…</div>}
        {error && <div className="robot-message" role="alert"><p>{error}</p><button className="btn" onClick={() => setAttempt(n => n + 1)}>Retry 3D</button></div>}
        {!loading && !error && <div className="robot-camera" role="group" aria-label="Robot camera controls">
          <button className="icon-button" aria-label="Rotate view left" onClick={() => scene.current?.rotate(-1)}><ArrowLeft size={13}/></button>
          <button className="icon-button" aria-label="Rotate view right" onClick={() => scene.current?.rotate(1)}><ArrowRight size={13}/></button>
          <button className="icon-button" aria-label="Zoom in on robot" onClick={() => scene.current?.zoom(.85)}><ZoomIn size={13}/></button>
          <button className="icon-button" aria-label="Zoom out from robot" onClick={() => scene.current?.zoom(1.18)}><ZoomOut size={13}/></button>
          <button className="icon-button" aria-label="Reset robot camera" onClick={() => scene.current?.reset()}><RotateCcw size={13}/></button>
        </div>}
      </div>
      <div className="robot-joints" aria-label="Measured joint torque at replay cursor">
        <div className="robot-joint-heading"><span>Joint</span><span>Nm</span></div>
        {data.channels.map((channel, i) => <button key={channel.id} aria-pressed={highlighted.includes(channel.id)}
          aria-label={`Highlight ${channel.name} in robot and signals`} onClick={() => onHighlight(channel.id)}>
          <span><i style={{ background: COLORS[i] }}/>J{i + 1}</span><span className="mono">{sample?.channels.find(c => c.id === channel.id)?.value.toFixed(3) ?? '—'}</span>
        </button>)}
        <p className="mono">{sample ? `${sample.time.toFixed(3)} s` : 'No sample'}</p>
      </div>
    </div>
    <footer className="robot-footer" title={positions?.validation.scope}><span>{measured ? positions?.validation.mappingVerified ? 'Recorded angles · schematic frame' : 'Recorded angles · reference mapping; schematic frame' : positionError || 'No position sample at this cursor · fixed pose'}</span><span>{sample?.resolution === 'raw' ? 'Torque · 1 kHz raw' : 'Torque · 100 Hz overview'}</span></footer>
  </div>;
}
export type Interval = { start: number; end: number };
export type Channel = { id: string; name: string; unit: string; values: number[] };
export type Marker = { id: string; timeSeconds: number; kind: 'publisher_annotation'; label: string; source: string };
export type DemoCase = { id: string; title: string; recordingId: string; interval: Interval; note: string };
export type DemoData = {
  demoCase?: DemoCase;
  recording: { id: string; name: string; durationSeconds: number; sampleRateHz: number; displaySampleRateHz: number; sourceUrl: string; archive: string; channelCount: number; eventCount: number };
  times: number[];
  channels: Channel[];
  events: Marker[];
  detail: { startSeconds: number; endSeconds: number; times: number[]; channels: Channel[] };
};
export type WindowData = { times: number[]; channels: Channel[]; resolution: 'raw' | 'display'; sampleRateHz: number };
export type EvidenceLink = { channelId: string; channelIds?: string[]; label: string; interval: Interval };
export type Analysis = { text: string; evidence: EvidenceLink[]; tools: string[]; resolution: 'raw' | 'display' };

